-- Migration 015: FY2027 Targets — Complete (see Python wrapper for details)
-- Schema changes
ALTER TABLE targets DROP CONSTRAINT IF EXISTS targets_target_bottles_check;
ALTER TABLE targets ADD COLUMN IF NOT EXISTS channel_id UUID REFERENCES channels(id);
ALTER TABLE targets DROP CONSTRAINT IF EXISTS target_has_owner;
ALTER TABLE targets ADD CONSTRAINT target_has_owner CHECK (
    (rep_id IS NOT NULL)::int + (territory_id IS NOT NULL)::int + (channel_id IS NOT NULL)::int = 1
);

-- Rose-Mary 500ml
    standard_bottle_equivalent, tier, is_active, created_by)
SELECT p.id, 'RM500', 'Rose-Mary 500ml', 500, ROUND((500.0/750.0)::numeric,4), ps.tier, TRUE, 'migration_015'
FROM products p JOIN product_skus ps ON ps.product_id=p.id AND ps.sku_code='RM001'
WHERE p.product_name='Rose-Mary'
  AND NOT EXISTS (SELECT 1 FROM product_skus WHERE sku_code='RM500');

-- Library Collection canonical product
SELECT 'DLIB','Library Collection','PREMIUM',TRUE,'migration_015'
WHERE NOT EXISTS (SELECT 1 FROM products WHERE product_code='DLIB');

-- Library Collection aggregate SKU
    tier, is_active, product_id, created_by)
SELECT 'DLIB','Library Collection (aggregate)',750,1.0,'PREMIUM',TRUE,p.id,'migration_015'
FROM products p WHERE p.product_code='DLIB'
  AND NOT EXISTS (SELECT 1 FROM product_skus WHERE sku_code='DLIB');

